    // Raw transport, callback transaction boundary and closed wire shapes.
    for(const auto& item:dw018_fixture::cases())for(const auto p:{ScriptControlProfile::Closed,ScriptControlProfile::Foreground})suite.test("fixed predata numeric same-PC source trace "+item.name+(p==ScriptControlProfile::Closed?" Closed":" Foreground"),[&,p]{Host h;nnn::CExecScript vm(h);h.vm=&vm;h.apply=false;status(vm.LoadBytes(fixture(item.filename),item.name,{},nullptr,p));for(const auto& step:item.steps){const auto r=vm.Exec();status(r.status);need(r.return_code==step.return_code&&r.pc==step.pc&&vm.GetCallDepth()==step.frames.size(),"source return/PC/frames");}need(json(h.events)==item.callback_json&&h.pcs.size()==item.callback_states.size()&&h.variable_reads==0,"source callback tuple or raw lookup");for(std::size_t i=0;i<h.pcs.size();++i)need(h.pcs[i]==item.callback_states[i].pc,"callback PC advance");need(!h.controller.StopHostState().pre_received_name&&h.controller.StopHostState().no_wait_same_character[2]==12,"PreData delayed into numeric");});
    suite.test("all work prepaid before first PreData budgets0 through10",[]{for(std::uint64_t budget=0;budget<=11;++budget){Host h;nnn::CExecScript vm(h);h.vm=&vm;auto w=decoded("voice_stop_labels.spt");w[39]=3;w[40]=0x66660002U;w[41]=end;w[42]=3;w[43]=0x66660002U;w[44]=end;load(vm,w);const auto r=vm.Exec(budget);status(r.status,budget<11?ErrorCode::BudgetExhausted:ErrorCode::Ok);need(r.work_used==(budget==0?0U:budget<8?1U:budget<11?8U:11U)&&h.events.size()==(budget<8?0U:2U)&&h.stops.size()==(budget<8?0U:1U)&&vm.GetPC()==(budget==0?0U:budget<8?32U:39U),"prepaid callback/PC boundary");need(h.controller.StopHostState().pre_received_name.has_value()==(budget<8),"PreData happened before complete payment");}});
    suite.test("default numeric rejection retains already delivered PreData",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;h.base_numeric=true;load(vm,decoded("voice_stop_labels.spt"));const auto r=vm.Exec();status(r.status);need(r.pc==45&&h.events.size()==3&&!h.controller.StopHostState().pre_received_name&&h.controller.StopHostState().no_wait_same_character[2]==12&&h.skipped==std::vector<std::tuple<Word,Word,Word>>{{32,0x66660007U,voice}},"default decline lost PreData or fallback");});
    suite.test("PreData may change live skip and nextfade before numeric",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;h.policy.auto_message=1;h.on_pre=[&]{h.SetSkipFlags(flags(4));status(h.controller.SetNextFade(2));};load(vm,decoded("voice_stop_labels.spt"));status(vm.Exec().status);need(h.stops.empty()&&h.controller.StopHostState().no_wait_same_character[2]==0&&h.controller.State().next_fade_units==0&&h.controller.State().channels[2].work[15]==1&&vm.GetPC()==45,"numeric read a pre-PreData snapshot");});
    suite.test("throwing PreData prevents numeric and retries PreData",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;int side=0;h.on_pre=[&]{++side;throw std::runtime_error("predata");};load(vm,decoded("voice_stop_labels.spt"));status(vm.Exec().status,ErrorCode::CallbackFailed);need(vm.GetPC()==32&&h.events.size()==1&&h.retained.empty()&&!h.controller.StopHostState().pre_received_name&&side==1,"PreData failure rollback or numeric dispatch");h.on_pre=[&]{++side;};status(vm.Exec().status);need(side==2&&h.events.size()==4&&h.retained.size()==1,"PreData not replayed on retry");});
    suite.test("numeric false or throw preserves predata and external effects",[]{for(const bool throws:{false,true}){Host h;nnn::CExecScript vm(h);h.vm=&vm;int effects=0;h.on_pre=[&]{++effects;h.SetSkipFlags(flags(8));};h.on_numeric=[&]{++effects;if(throws)throw 17;};h.accept=false;load(vm,decoded("voice_stop_labels.spt"));const auto r=vm.Exec();status(r.status,throws?ErrorCode::CallbackFailed:ErrorCode::Ok);need(r.pc==(throws?32U:45U)&&effects==2&&h.events.size()==(throws?2U:3U)&&!h.controller.StopHostState().pre_received_name&&h.controller.StopHostState().no_wait_same_character[2]==12,"numeric failure effects or step");if(!throws)need(h.skipped==std::vector<std::tuple<Word,Word,Word>>{{32,0x66660007U,voice}},"numeric decline fallback");}});
    suite.test("actual typed Stop rejection keeps PreData and early host mutation",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;h.outputs.stop={};load(vm,decoded("voice_stop_labels.spt"));const auto r=vm.Exec();status(r.status);need(r.pc==45&&!h.controller.StopHostState().pre_received_name&&h.controller.StopHostState().no_wait_same_character[2]==0&&h.controller.State().channels[2].work[15]==1&&h.skipped==std::vector<std::tuple<Word,Word,Word>>{{32,0x66660007U,voice}},"typed Stop decline lost writes or fallback");});
    suite.test("actual physical exception maps CallbackFailed with current PC",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;h.on_stop=[]{throw std::runtime_error("backend");};load(vm,decoded("voice_stop_labels.spt"));status(vm.Exec().status,ErrorCode::CallbackFailed);need(vm.GetPC()==32&&h.events.size()==2&&h.controller.State().channels[2].fade_target_volume==0&&h.controller.State().channels[2].work[15]==1&&!h.controller.StopHostState().pre_received_name,"physical VM exception order");});
    suite.test("VM reentry Busy in both callbacks and retained vector ownership",[]{Host h;nnn::CExecScript vm(h);h.vm=&vm;const auto w=decoded("voice_stop_labels.spt");const auto busy=[&]{need(vm.GetPC()==32,"callback PC");status(vm.Exec().status,ErrorCode::Busy);status(vm.LoadBytes(encoded(w),"nested"),ErrorCode::Busy);};h.on_pre=busy;h.on_numeric=busy;load(vm,w);status(vm.Exec().status);load(vm,w);need(h.retained==std::vector<std::vector<Value>>{{-1,2}},"owned numeric parameters changed on load");});
    for(const bool labels:{false,true})for(const auto p:{ScriptControlProfile::Closed,ScriptControlProfile::Foreground}){
        const std::string file=labels?"voice_stop_labels.spt":"voice_stop_legacy7.spt";
        const std::string tag=std::string(labels?" labels":" legacy")+(p==ScriptControlProfile::Closed?" Closed":" Foreground");
        suite.test("channel filename tail forms use structural rules"+tag,[=]{for(const std::size_t field:{36U,37U,38U}){auto w=decoded(file);w[field]=field==36?0U:1U;if(field==36)reject(w,ErrorCode::InvalidFormat,p);else format_expect_numeric(encoded(w),p,0x66660007U,voice,{UINT32_MAX,field==37?1U:2U},field==38?1U:0U);}});
        suite.test("coherent no-tail exact parameters dispatch"+tag,[=]{format_expect_numeric(encoded(variant(file,{6,0x66660007U,voice,2,UINT32_MAX,2})),p,0x66660007U,voice,{UINT32_MAX,2});});
        suite.test("coherent other counts dispatch"+tag,[=]{format_expect_numeric(encoded(variant(file,{4,0x66660007U,voice,0})),p,0x66660007U,voice,{});format_expect_numeric(encoded(variant(file,{5,0x66660007U,voice,1,UINT32_MAX})),p,0x66660007U,voice,{UINT32_MAX});auto w=decoded(file);w[35]=3;format_expect_numeric(encoded(w),p,0x66660007U,voice,{UINT32_MAX,2,0});});
        suite.test("missing contradictory count and extra tails are invalid"+tag,[=]{reject(variant(file,{3,0x66660007U,voice}),ErrorCode::InvalidFormat,p);for(const Word count:{0U,1U,4U,UINT32_MAX}){auto w=decoded(file);w[35]=count;reject(w,ErrorCode::InvalidFormat,p);}});
        suite.test("voice stop dispatches without executable fallthrough"+tag,[=]{auto w=decoded(file);w.erase(w.begin()+39,w.begin()+48);for(const std::size_t field:{5U,7U,9U,16U,17U,18U,20U,21U,22U,23U})if(w[field])w[field]-=9;for(const auto& pair:{std::make_pair(5U,4U),std::make_pair(7U,6U)})for(Word i=0;i<w[pair.second];++i)w[w[pair.first]+i]-=9;format_expect_numeric(encoded(w),p,0x66660007U,voice,{UINT32_MAX,2},0U);});
    }
